# owner: platform
"""Snap span edges to a fixed step, like a quarter hour."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

# ---
def label_rounded_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Snap each span to the step and label it."""
    _check_step(step)
    snapped = [_snap_span(span, step) for span in spans]
    return [_label(span) for span in snapped]

def _check_step(step: int) -> None:
    """Raise ValueError unless step divides an hour."""
    usable = isinstance(step, int) and 0 < step <= 60
    if not usable or 60 % step != 0:
        raise ValueError(
            f"step must divide an hour evenly: {step!r}"
        )

def _snap(minutes: int, step: int) -> int:
    """Nearest multiple of step. Exact halves round up."""
    return (minutes + step // 2) // step * step

def _snap_span(span: Span, step: int) -> Span:
    start = _snap(span.start, step)
    end = _snap(span.end, step)
    return Span(start, end)

def _label(span: Span) -> str:
    hours, rest = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {rest}m)"
